ALTER TABLE public.questions ADD COLUMN source_number integer, ADD COLUMN source_page integer; COMMENT ON COLUMN public.questions.source_number IS 'Original parent question number in the uploaded test'; COMMENT ON COLUMN public.questions.source_page IS 'One-based source PDF page'; UPDATE public.questions SET source_number = substring(stem from '^(?:Original question |Question )?([0-9]+)')::integer WHERE stem ~ '^(Original question |Question )?[0-9]+';